<?php
declare(strict_types=1);
use ImAuthenticator\Security;use ImAuthenticator\Web;
$services=require dirname(__DIR__).'/src/bootstrap.php';extract($services,EXTR_SKIP);$admin=$auth->requireAdmin();$templates=$toolkit->templates();$templateOptions='<option value="">— bez szablonu —</option>';$templateData=[];foreach($templates as$t){$templateOptions.='<option value="'.Web::e($t['slug']).'">'.Web::e($t['name']).'</option>';$defaults=json_decode((string)$t['defaults_json'],true);$templateData[$t['slug']]=['app_type'=>$t['app_type'],'integration_type'=>$t['integration_type'],'scopes'=>is_array($defaults)?($defaults['scopes']??['openid','profile','email','roles']):['openid','profile','email','roles'],'instructions'=>$t['instructions']??''];}$json=htmlspecialchars(json_encode($templateData,JSON_UNESCAPED_SLASHES|JSON_UNESCAPED_UNICODE|JSON_THROW_ON_ERROR),ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');$content='<div class="page-head"><div><h1>Dodaj aplikację</h1><p>Kreator klienta OAuth/OpenID Connect — ręcznie albo z gotowego presetu.</p></div><a class="button" href="/admin/applications">Anuluj</a></div><form method="post" action="/admin/applications" id="appWizard" class="card wizard"><input type="hidden" name="_csrf" value="'.Web::e(Security::csrfToken()).'"><section class="wizard-step active" data-step="1"><div class="step-label">Krok 1 z 5</div><h2>Dane aplikacji</h2><label>Szablon<select id="templateSelect">'.$templateOptions.'</select></label><div class="hint" id="templateHint">Szablon ustawia typ integracji i minimalny zestaw scopes. Client Secret nigdy nie jest wpisywany ręcznie.</div><label>Nazwa aplikacji<input name="name" required></label><label>Opis<textarea name="description" rows="3"></textarea></label><label>Adres aplikacji<input type="url" name="url" placeholder="https://xyz.example.com" required></label><label>Ikona/logo URL<input type="url" name="icon"></label><label>Typ aplikacji<select name="app_type" id="appType"><option value="website">Strona WWW</option><option value="wordpress">WordPress</option><option value="php">Własna aplikacja PHP</option><option value="spa">SPA</option><option value="mobile">Aplikacja mobilna</option><option value="oidc" selected>Generic OpenID Connect</option><option value="m2m">Machine-to-Machine</option></select></label></section><section class="wizard-step" data-step="2"><div class="step-label">Krok 2 z 5</div><h2>Typ integracji</h2><label>Integracja<select name="integration_type" id="integrationType"><option value="generic_oidc">Generic OpenID Connect</option><option value="wordpress_oidc">WordPress / OpenID Connect</option><option value="public_pkce">Public Client + PKCE</option><option value="client_credentials">Machine-to-Machine</option></select></label><div class="hint" id="integrationHint"></div></section><section class="wizard-step" data-step="3"><div class="step-label">Krok 3 z 5</div><h2>Callback / Redirect URI</h2><label>Redirect URI — jeden na linię<textarea name="redirect_uris" id="redirectUris" rows="5" placeholder="https://xyz.example.com/oauth/callback" required></textarea></label><div class="hint" id="redirectHint"></div></section><section class="wizard-step" data-step="4"><div class="step-label">Krok 4 z 5</div><h2>Generowanie klienta</h2><p>System wygeneruje kryptograficznie Client ID i — dla confidential client — Client Secret.</p><label>Scopes<input name="scopes" id="scopePreview" value="openid profile email roles" readonly></label></section><section class="wizard-step" data-step="5"><div class="step-label">Krok 5 z 5</div><h2>Dostęp użytkowników</h2><label>Polityka dostępu<select name="access_policy"><option value="none" selected>Brak dostępu — administrator musi przypisać użytkowników</option><option value="all">Wszyscy użytkownicy</option><option value="users">Wybrani użytkownicy</option><option value="groups">Wybrane grupy</option><option value="roles">Wybrane role</option><option value="mixed">Reguły mieszane</option></select></label><div class="alert warning">Domyślna polityka nie udostępnia aplikacji żadnemu użytkownikowi.</div></section><div class="wizard-actions"><button type="button" id="prevStep">Wstecz</button><button type="button" class="primary" id="nextStep">Dalej</button><button type="submit" class="primary hidden" id="createApp">Utwórz aplikację</button></div></form><script>const templates=JSON.parse("'.addslashes($json).'");let s=1,templateScopes=null;const steps=[...document.querySelectorAll(".wizard-step")],next=document.getElementById("nextStep"),prev=document.getElementById("prevStep"),create=document.getElementById("createApp"),type=document.getElementById("appType"),integration=document.getElementById("integrationType"),redirects=document.getElementById("redirectUris"),redirectHint=document.getElementById("redirectHint"),scope=document.getElementById("scopePreview"),hint=document.getElementById("integrationHint"),template=document.getElementById("templateSelect"),templateHint=document.getElementById("templateHint");function show(){steps.forEach(x=>x.classList.toggle("active",Number(x.dataset.step)===s));prev.disabled=s===1;next.classList.toggle("hidden",s===5);create.classList.toggle("hidden",s!==5)}function sync(preserveScopes=false){const m2m=integration.value==="client_credentials";redirects.required=!m2m;redirects.disabled=m2m;redirectHint.textContent=m2m?"Machine-to-Machine nie używa Redirect URI.":"Wildcardy są zabronione. HTTPS jest wymagany poza localhost.";if(!preserveScopes)scope.value=m2m?"roles":"openid profile email roles";hint.textContent=integration.value==="public_pkce"?"Public Client bez sekretu; PKCE S256 jest obowiązkowe.":(m2m?"Confidential Client z Client Credentials.":"Authorization Code / OIDC.")}function preset(){template.value="";templateScopes=null;integration.value=type.value==="wordpress"?"wordpress_oidc":(["spa","mobile"].includes(type.value)?"public_pkce":(type.value==="m2m"?"client_credentials":"generic_oidc"));sync()}template.onchange=()=>{const t=templates[template.value];if(!t){preset();return}type.value=t.app_type;integration.value=t.integration_type;templateScopes=Array.isArray(t.scopes)?t.scopes:null;sync(true);scope.value=(templateScopes||["openid","profile","email","roles"]).join(" ");templateHint.textContent=t.instructions||"Preset zastosowany."};next.onclick=()=>{if(s<5)s++;show()};prev.onclick=()=>{if(s>1)s--;show()};type.onchange=preset;integration.onchange=()=>{template.value="";templateScopes=null;sync()};preset();show();</script>';Web::page('Dodaj aplikację',$content,$admin);
